#!/usr/bin/env python3
"""Enrich 250-Class-250 — next 50 stubs (batches 11-15)."""
import json, os, datetime, unicodedata

FOLDER = "/home/manasa151/annals-of-the-world/data/appwrite-export/entities/250-Class-250"
NOW = datetime.datetime.now(datetime.timezone.utc).isoformat()

def _norm(s):
    table = str.maketrans({
        'ł':'l','Ł':'L','ø':'o','Ø':'O','ð':'d','Ð':'D',
        'þ':'th','ß':'ss','æ':'ae','Æ':'Ae','đ':'d','Đ':'D',
        'ħ':'h','Ħ':'H','ı':'i',
    })
    s = s.translate(table)
    return unicodedata.normalize("NFD", s).encode("ascii","ignore").decode("ascii").lower()

def find_file(slug):
    direct = os.path.join(FOLDER, f"250{slug}.json")
    if os.path.exists(direct): return direct
    norm_slug = _norm(slug)
    for f in os.listdir(FOLDER):
        if f.endswith(".json") and f.startswith("250"):
            if _norm(f[3:-5]) == norm_slug:
                return os.path.join(FOLDER, f)
    return None

def enrich(slug, data):
    fpath = find_file(slug)
    if not fpath:
        print(f"  SKIP (not found): {slug}"); return
    try:
        raw = json.load(open(fpath, encoding="utf-8"))
    except Exception as ex:
        print(f"  ERROR loading {fpath}: {ex}"); return
    e = raw["entities"][0]
    dj = e.get("detailsJson", "{}")
    det = json.loads(dj) if isinstance(dj, str) else (dj or {})
    old_summary = e.get("summary", "")
    e["summary"] = data["summary"]
    e["importanceScore"] = 6
    e["historicalSignificance"] = data["hs"]
    e["_unsyncedEdits"] = True
    det["causes"] = data["causes"]
    det["effects"] = data["effects"]
    det["relationships"] = data["rels"]
    det["_unsyncedEdits"] = True
    det.setdefault("_editLog", []).append({
        "timestamp": NOW, "editorId": "vscode-copilot",
        "field": "summary", "oldValue": old_summary[:80], "newValue": data["summary"][:80]
    })
    e["detailsJson"] = json.dumps(det, ensure_ascii=False)
    with open(fpath, "w", encoding="utf-8") as fh:
        json.dump(raw, fh, ensure_ascii=False, indent=2)
    print(f"  OK: {e.get('name', slug)}")

